import { Command } from "commander";
import fs from "node:fs/promises";
import path from "node:path";
import sharp from "sharp";

const ALPHA_THRESHOLD = 0.002;
const MAX_ALPHA = 0.99;
const DEFAULT_LOGO_VALUE = 255;

const ASSET_BASE64 = {
  48: "",
  96: "",
} as const;

type WatermarkConfig = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type WatermarkOptions = {
  /** Shorthand: sets sizeX/sizeY when those are omitted. */
  size?: number;
  /** Override watermark template width in pixels. */
  sizeX?: number;
  /** Override watermark template height in pixels. */
  sizeY?: number;
  /** Override margin from the right edge in pixels. */
  marginX?: number;
  /** Override margin from the bottom edge in pixels. */
  marginY?: number;
  /**
   * Assumed watermark logo strength multiplier (default 1 → logo level 255).
   * Values above 1 darken the restored image; values below 1 brighten it.
   */
  brightness?: number;
};

const BASE_TEMPLATE_SIZES = [48, 96] as const;
type BaseTemplateSize = (typeof BASE_TEMPLATE_SIZES)[number];

const alphaMapCache = new Map<string, Float32Array>();

function alphaMapCacheKey(width: number, height: number): string {
  return `${width}x${height}`;
}

const MAX_BRIGHTNESS = 8;

function resolveLogoValue(brightness?: number): number {
  const factor = brightness ?? 1;
  if (!Number.isFinite(factor) || factor <= 0) {
    throw new Error(`brightness must be a positive number, got ${brightness}`);
  }
  if (factor > MAX_BRIGHTNESS) {
    throw new Error(
      `brightness must be at most ${MAX_BRIGHTNESS}, got ${brightness}`,
    );
  }
  return DEFAULT_LOGO_VALUE * factor;
}

function pickBaseTemplateSize(targetSize: number): BaseTemplateSize {
  return Math.abs(targetSize - 48) <= Math.abs(targetSize - 96) ? 48 : 96;
}

function alphaMapFromRaw(
  data: Buffer,
  width: number,
  height: number,
): Float32Array {
  const alphaMap = new Float32Array(width * height);
  for (let i = 0; i < alphaMap.length; i++) {
    const idx = i * 4;
    alphaMap[i] = Math.max(data[idx], data[idx + 1], data[idx + 2]) / 255.0;
  }
  return alphaMap;
}

async function getAlphaMap(
  width: number,
  height: number,
): Promise<Float32Array> {
  if (!Number.isInteger(width) || width < 1) {
    throw new Error(`Alpha map width must be a positive integer, got ${width}`);
  }
  if (!Number.isInteger(height) || height < 1) {
    throw new Error(
      `Alpha map height must be a positive integer, got ${height}`,
    );
  }

  const cacheKey = alphaMapCacheKey(width, height);
  const cached = alphaMapCache.get(cacheKey);
  if (cached) return cached;

  const baseSize = pickBaseTemplateSize(Math.max(width, height));
  const buffer = Buffer.from(ASSET_BASE64[baseSize], "base64");

  let pipeline = sharp(buffer).ensureAlpha();
  if (width !== baseSize || height !== baseSize) {
    pipeline = pipeline.resize(width, height, {
      kernel: "lanczos3",
      fit: "fill",
    });
  }

  const { data, info } = await pipeline
    .raw()
    .toBuffer({ resolveWithObject: true });

  if (info.width !== width || info.height !== height) {
    throw new Error(
      `Unexpected alpha map dimensions for ${width}x${height} watermark: ${info.width}x${info.height}`,
    );
  }

  const alphaMap = alphaMapFromRaw(data, width, height);
  alphaMapCache.set(cacheKey, alphaMap);
  return alphaMap;
}

function getWatermarkInfo(
  width: number,
  height: number,
  options?: WatermarkOptions,
): WatermarkConfig {
  const isLarge = width > 1024 && height > 1024;
  const defaultSize = isLarge ? 96 : 48;
  const templateWidth = options?.sizeX ?? options?.size ?? defaultSize;
  const templateHeight = options?.sizeY ?? options?.size ?? defaultSize;
  const defaultMargin = isLarge ? 64 : 32;
  const marginX = options?.marginX ?? defaultMargin;
  const marginY = options?.marginY ?? defaultMargin;
  return {
    x: width - marginX - templateWidth,
    y: height - marginY - templateHeight,
    width: templateWidth,
    height: templateHeight,
  };
}

function removeWatermarkInPlace(
  imageData: Uint8Array,
  imageWidth: number,
  imageHeight: number,
  alphaMap: Float32Array,
  position: WatermarkConfig,
  logoValue: number,
): void {
  const { x, y, width, height } = position;

  if (x < 0 || y < 0 || x + width > imageWidth || y + height > imageHeight) {
    return;
  }

  for (let row = 0; row < height; row++) {
    for (let col = 0; col < width; col++) {
      const imgIdx = ((y + row) * imageWidth + (x + col)) * 4;
      const alphaIdx = row * width + col;

      let alpha = alphaMap[alphaIdx];
      if (alpha < ALPHA_THRESHOLD) continue;
      alpha = Math.min(alpha, MAX_ALPHA);

      for (let c = 0; c < 3; c++) {
        const watermarked = imageData[imgIdx + c];
        const original = (watermarked - alpha * logoValue) / (1.0 - alpha);
        imageData[imgIdx + c] = Math.max(
          0,
          Math.min(255, Math.round(original)),
        );
      }
    }
  }
}

function outputPathFor(inputPath: string): string {
  const parsed = path.parse(inputPath);
  return path.join(parsed.dir, `${parsed.name}-nomark${parsed.ext}`);
}

function originalPathFromNomark(inputPath: string): string {
  const parsed = path.parse(inputPath);
  const originalName = parsed.name.replace(/-nomark$/i, "");
  return path.join(parsed.dir, `${originalName}${parsed.ext}`);
}

async function collectPngFiles(targetPath: string): Promise<string[]> {
  const stats = await fs.stat(targetPath);

  if (stats.isFile()) {
    if (!targetPath.toLowerCase().endsWith(".png")) return [];
    if (targetPath.toLowerCase().endsWith("-nomark.png")) return [];
    return [targetPath];
  }

  const results: string[] = [];
  const entries = await fs.readdir(targetPath, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(targetPath, entry.name);
    if (entry.isDirectory()) {
      results.push(...(await collectPngFiles(fullPath)));
      continue;
    }

    const lower = entry.name.toLowerCase();
    if (!lower.endsWith(".png")) continue;
    if (lower.endsWith("-nomark.png")) continue;
    results.push(fullPath);
  }

  return results;
}

async function collectNomarkPngFiles(targetPath: string): Promise<string[]> {
  const stats = await fs.stat(targetPath);

  if (stats.isFile()) {
    if (!targetPath.toLowerCase().endsWith("-nomark.png")) return [];
    return [targetPath];
  }

  const results: string[] = [];
  const entries = await fs.readdir(targetPath, { withFileTypes: true });
  for (const entry of entries) {
    const fullPath = path.join(targetPath, entry.name);
    if (entry.isDirectory()) {
      results.push(...(await collectNomarkPngFiles(fullPath)));
      continue;
    }

    const lower = entry.name.toLowerCase();
    if (!lower.endsWith("-nomark.png")) continue;
    results.push(fullPath);
  }

  return results;
}

export async function removeGeminiWatermark(
  inputPath: string,
  options?: WatermarkOptions,
): Promise<void> {
  const absolute = path.resolve(inputPath);
  const files = await collectPngFiles(absolute);

  if (files.length === 0) {
    console.log("No PNG files found to process.");
    return;
  }

  let processed = 0;
  for (const filePath of files) {
    const { data, info } = await sharp(filePath)
      .ensureAlpha()
      .raw()
      .toBuffer({ resolveWithObject: true });

    const config = getWatermarkInfo(info.width, info.height, options);
    const alphaMap = await getAlphaMap(config.width, config.height);
    const logoValue = resolveLogoValue(options?.brightness);

    removeWatermarkInPlace(
      data,
      info.width,
      info.height,
      alphaMap,
      config,
      logoValue,
    );

    const outputPath = outputPathFor(filePath);
    await sharp(data, {
      raw: {
        width: info.width,
        height: info.height,
        channels: info.channels,
      },
    })
      .png()
      .toFile(outputPath);

    processed++;
    console.log(`Processed ${processed}/${files.length}: ${outputPath}`);
  }
}

export async function applyNomarkOverwrites(inputPath: string): Promise<void> {
  const absolute = path.resolve(inputPath);
  const files = await collectNomarkPngFiles(absolute);

  if (files.length === 0) {
    console.log("No *-nomark.png files found to apply.");
    return;
  }

  let applied = 0;
  for (const nomarkPath of files) {
    const originalPath = originalPathFromNomark(nomarkPath);
    await fs.rm(originalPath, { force: true });
    await fs.rename(nomarkPath, originalPath);
    applied++;
    console.log(`Applied ${applied}/${files.length}: ${originalPath}`);
  }
}

function parseMarginOption(value: string, flag: string): number {
  const margin = Number.parseInt(value, 10);
  if (!Number.isFinite(margin) || margin < 0) {
    throw new Error(`${flag} must be a non-negative integer`);
  }
  return margin;
}

function parseSizeOption(value: string, flag: string): number {
  const size = Number.parseInt(value, 10);
  if (!Number.isInteger(size) || size < 1) {
    throw new Error(`${flag} must be a positive integer`);
  }
  return size;
}

function parseBrightnessOption(value: string): number {
  const brightness = Number.parseFloat(value);
  if (!Number.isFinite(brightness) || brightness <= 0) {
    throw new Error("--brightness must be a positive number");
  }
  if (brightness > MAX_BRIGHTNESS) {
    throw new Error(`--brightness must be at most ${MAX_BRIGHTNESS}`);
  }
  return brightness;
}

const program = new Command();

program
  .name("remove-gemini-watermark")
  .description(
    "Scan a file/folder for PNG files, remove Gemini watermark, and output *-nomark.png files.",
  )
  .option(
    "--apply-nomark",
    "Rename *-nomark.png to original filename and overwrite old files",
  )
  .option(
    "--size-x <pixels>",
    "Watermark template width in pixels; overrides auto-detect",
    (value: string) => parseSizeOption(value, "--size-x"),
  )
  .option(
    "--size-y <pixels>",
    "Watermark template height in pixels; overrides auto-detect",
    (value: string) => parseSizeOption(value, "--size-y"),
  )
  .option(
    "--size <pixels>",
    "Shorthand for --size-x and --size-y with the same value",
    (value: string) => parseSizeOption(value, "--size"),
  )
  .option(
    "--margin-x <pixels>",
    "Margin from the right edge in pixels; overrides auto-detect",
    (value: string) => parseMarginOption(value, "--margin-x"),
  )
  .option(
    "--margin-y <pixels>",
    "Margin from the bottom edge in pixels; overrides auto-detect",
    (value: string) => parseMarginOption(value, "--margin-y"),
  )
  .option(
    "--margin <pixels>",
    "Shorthand for --margin-x and --margin-y with the same value",
    (value: string) => parseMarginOption(value, "--margin"),
  )
  .option(
    "--brightness <factor>",
    "Logo strength 0–8 (default 1). Above 1 darkens output; below 1 brightens",
    parseBrightnessOption,
  )
  .argument("<path>", "Path to a PNG file or directory to scan recursively")
  .action(
    async (
      inputPath: string,
      options: {
        applyNomark?: boolean;
        size?: number;
        sizeX?: number;
        sizeY?: number;
        margin?: number;
        marginX?: number;
        marginY?: number;
        brightness?: number;
      },
    ) => {
      try {
        if (options.applyNomark) {
          await applyNomarkOverwrites(inputPath);
          return;
        }
        const watermarkOptions: WatermarkOptions = {};
        if (options.sizeX !== undefined) watermarkOptions.sizeX = options.sizeX;
        if (options.sizeY !== undefined) watermarkOptions.sizeY = options.sizeY;
        if (options.size !== undefined) {
          if (options.sizeX === undefined)
            watermarkOptions.sizeX = options.size;
          if (options.sizeY === undefined)
            watermarkOptions.sizeY = options.size;
        }
        if (options.marginX !== undefined)
          watermarkOptions.marginX = options.marginX;
        if (options.marginY !== undefined)
          watermarkOptions.marginY = options.marginY;
        if (options.margin !== undefined) {
          if (options.marginX === undefined)
            watermarkOptions.marginX = options.margin;
          if (options.marginY === undefined)
            watermarkOptions.marginY = options.margin;
        }
        if (options.brightness !== undefined)
          watermarkOptions.brightness = options.brightness;
        await removeGeminiWatermark(
          inputPath,
          Object.keys(watermarkOptions).length > 0
            ? watermarkOptions
            : undefined,
        );
      } catch (error) {
        console.error("Failed to remove Gemini watermark:", error);
        process.exitCode = 1;
      }
    },
  );

program.parse(process.argv);
